#!/usr/bin/env node
/**
 * Guards for the two things an answer engine actually reads: the full-text file
 * and the per-page dates.
 *
 * The failure mode here is quiet. If /llms-full.txt goes stale, nothing breaks,
 * no link 404s, and the site keeps looking fine -- it just publishes last week's
 * numbers to the one reader that quotes them verbatim. So the file is checked
 * against the same params every page is checked against, and against the sitemap
 * so a new page cannot be added without appearing in it.
 *
 * Generated by website/tools/build_llms_full.py and website/tools/inject_facts.py.
 */

import assert from "node:assert/strict";
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { test } from "node:test";

const ROOT = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const WEB = ROOT + "website";
const params = JSON.parse(readFileSync(ROOT + "contracts/params.json", "utf8"));
const a = params.airdrop;

const read = (rel) => readFileSync(WEB + rel, "utf8");
const full = existsSync(WEB + "/llms-full.txt") ? read("/llms-full.txt") : "";
const fullZh = existsSync(WEB + "/llms-full-zh.txt") ? read("/llms-full-zh.txt") : "";
const llms = read("/llms.txt");
const robots = read("/robots.txt");
const vercel = JSON.parse(read("/vercel.json"));

const th = (n) => n.toLocaleString("en-US");

function ldBlocks(html) {
  return [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => m[1]);
}

const ALL = (() => {
  const out = [];
  for (const dir of ["", "news/", "zh/", "zh/news/"]) {
    for (const name of readdirSync(WEB + "/" + dir)) {
      if (name.endsWith(".html")) out.push({ rel: dir + name, html: read("/" + dir + name) });
    }
  }
  return out;
})();

test("the full-text files exist and are a sane size", () => {
  assert.ok(full.length > 60_000, `llms-full.txt is only ${full.length} chars — regenerate it`);
  assert.ok(full.length < 400_000, `llms-full.txt is ${full.length} chars — too large for one fetch`);
  assert.ok(fullZh.length > 15_000, `llms-full-zh.txt is only ${fullZh.length} chars`);
  assert.ok(full.endsWith("\n"), "llms-full.txt must end with a newline");
  assert.ok(fullZh.endsWith("\n"), "llms-full-zh.txt must end with a newline");
});

test("the header names the params version it was built from", () => {
  // The one staleness signal a reader can act on: if this says v7 while
  // params.json says v8, every number below it is suspect.
  for (const [name, text] of [["en", full], ["zh", fullZh]]) {
    assert.ok(
      text.includes(`v${params.version}`) && text.includes(String(params.updatedAt)),
      `${name}: header must state params v${params.version} (${params.updatedAt})`,
    );
  }
});

test("the full-text file carries no markup and no chrome", () => {
  for (const [name, text] of [["en", full], ["zh", fullZh]]) {
    for (const junk of ["<div", "<script", "<nav", "<footer", "<span", "nav-drop", "&amp;", "&nbsp;"]) {
      assert.ok(!text.includes(junk), `${name}: raw markup survived into the text dump: ${junk}`);
    }
  }
});

test("every airdrop figure in the dump matches params.json", () => {
  for (const [name, text] of [["en", full], ["zh", fullZh]]) {
    assert.ok(text.includes(th(a.pool)), `${name}: pool ${a.pool} missing or not thousands-separated`);
    assert.ok(text.includes(`${a.perEntry} OMC`), `${name}: per-entry ${a.perEntry} OMC missing`);
    assert.ok(text.includes(th(a.poolSlots)), `${name}: slot count missing`);
    assert.ok(text.includes(`${a.claimCost.feeBnb} BNB`), `${name}: claim fee missing`);
  }
});

test("the dump does not describe the airdrop as a purchase", () => {
  // This is the file a summariser reads end to end, so a stray "entrance fee"
  // in it outweighs any number of careful sentences on the pages themselves.
  const banned = ["entrance fee", "paid airdrop", "cost to enter", "buy the airdrop", "入场费"];
  for (const [name, text] of [["en", full], ["zh", fullZh]]) {
    const lower = text.toLowerCase();
    for (const phrase of banned) {
      assert.ok(!lower.includes(phrase), `${name}: must not say "${phrase}"`);
    }
  }
});

test("every sitemap page appears in the dump, at its URL", () => {
  const sitemap = read("/sitemap.xml");
  const urls = [...sitemap.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map((m) => m[1]);
  assert.ok(urls.length > 20, "sitemap looks wrong");
  const missing = urls.filter((u) => {
    const zh = /\/zh(\/|$)/.test(new URL(u).pathname);
    return !(zh ? fullZh : full).includes(`URL: ${u} `);
  });
  assert.deepEqual(
    missing,
    [],
    `these sitemap URLs are not in the full-text dump — add them to build_llms_full.py and rerun: ${missing.join(", ")}`,
  );
});

test("llms.txt points at both full-text files", () => {
  assert.ok(llms.includes("https://omc.network/llms-full.txt"), "llms.txt must link llms-full.txt");
  assert.ok(llms.includes("https://omc.network/llms-full-zh.txt"), "llms.txt must link the Chinese full text");
  assert.ok(robots.includes("llms-full.txt"), "robots.txt should mention the full-text file");
});

test("both full-text files are served as CORS-readable plain text", () => {
  for (const source of ["/llms-full.txt", "/llms-full-zh.txt"]) {
    const rule = vercel.headers.find((h) => h.source === source);
    assert.ok(rule, `vercel.json has no header rule for ${source}`);
    const keys = Object.fromEntries(rule.headers.map((h) => [h.key, h.value]));
    assert.equal(keys["Access-Control-Allow-Origin"], "*", `${source} must be readable cross-origin`);
    assert.match(keys["Content-Type"], /text\/plain/, `${source} should be text/plain`);
  }
});

test("every page publishes a machine-readable date", () => {
  const bad = [];
  for (const { rel, html } of ALL) {
    const dated = ldBlocks(html).some((raw) => {
      try {
        const node = JSON.parse(raw);
        return node && /^\d{4}-\d{2}-\d{2}/.test(String(node.dateModified ?? ""));
      } catch {
        return false;
      }
    });
    if (!dated) bad.push(rel);
  }
  assert.deepEqual(bad, [], `pages without dateModified — run website/tools/inject_facts.py: ${bad.join(", ")}`);
});

test("every page shows the facts version it is quoting", () => {
  const bad = [];
  for (const { rel, html } of ALL) {
    const m = html.match(/<span class="facts-v">([\s\S]*?)<\/span>/);
    if (!m) {
      bad.push(`${rel} (no stamp)`);
      continue;
    }
    if (!m[1].includes(`v${params.version}`) || !m[1].includes(String(params.updatedAt))) {
      bad.push(`${rel} (stale: ${m[1].slice(0, 40)})`);
    }
  }
  assert.deepEqual(bad, [], `facts stamp missing or stale — run website/tools/inject_facts.py: ${bad.join(", ")}`);
});

test("the Chinese pages carry a Chinese stamp, the English ones do not", () => {
  for (const { rel, html } of ALL) {
    const m = html.match(/<span class="facts-v">([\s\S]*?)<\/span>/);
    if (!m) continue;
    if (rel.startsWith("zh/")) {
      assert.ok(m[1].includes("数据版本"), `${rel}: Chinese page should say 数据版本`);
    } else {
      assert.ok(m[1].startsWith("Facts"), `${rel}: English page should say Facts`);
    }
  }
});

test("every JSON-LD block on every page still parses", () => {
  // The injector edits these blocks with text surgery to keep the diff small,
  // which is exactly the kind of edit that can leave a trailing comma.
  const bad = [];
  for (const { rel, html } of ALL) {
    for (const raw of ldBlocks(html)) {
      try {
        JSON.parse(raw);
      } catch (err) {
        bad.push(`${rel}: ${err.message}`);
      }
    }
  }
  assert.deepEqual(bad, [], `broken JSON-LD — run website/tools/inject_facts.py: ${bad.join(" | ")}`);
});
